// Images
export const LOGO_BASE64 = "data:image/png;base64,";
export const FAVICON_BUFFER = Buffer.from('', 'base64');

// Combined JSX components (in load order)
export const FRONTEND_JSX = "\n// ========== services/LogService.jsx ==========\n/**\n * API Service for fetching logs and fields\n */\nconst LogService = {\n  async fetchLogs({ token, skip = 0, limit = 50, search = '', field = '_all', startDate = '', endDate = '' }) {\n    const params = new URLSearchParams({\n      token,\n      limit: limit.toString(),\n      skip: skip.toString()\n    });\n\n    if (search) params.append('search', search);\n    if (field && field !== '_all') params.append('field', field);\n    if (startDate) params.append('startDate', new Date(startDate).toISOString());\n    if (endDate) params.append('endDate', new Date(endDate).toISOString());\n\n    const response = await fetch('/api/logs?' + params.toString());\n    if (!response.ok) {\n      const data = await response.json();\n      throw new Error(data.message || 'Failed to fetch logs');\n    }\n    return response.json();\n  },\n\n  async fetchFields(token) {\n    const response = await fetch('/api/fields?token=' + encodeURIComponent(token));\n    if (!response.ok) {\n      const data = await response.json();\n      throw new Error(data.message || 'Failed to fetch fields');\n    }\n    return response.json();\n  }\n};\n\nwindow.LogService = LogService;\n\n\n// ========== services/ExportService.jsx ==========\n/**\n * Export Service for generating XLSX files\n */\nconst ExportService = {\n  async fetchAllLogs({ token, search = '', field = '_all', startDate = '', endDate = '' }) {\n    const params = new URLSearchParams({\n      token,\n      limit: '100000', // Fetch all logs\n      skip: '0'\n    });\n\n    if (search) params.append('search', search);\n    if (field && field !== '_all') params.append('field', field);\n    if (startDate) params.append('startDate', new Date(startDate).toISOString());\n    if (endDate) params.append('endDate', new Date(endDate).toISOString());\n\n    const response = await fetch('/api/logs?' + params.toString());\n    if (!response.ok) {\n      const data = await response.json();\n      throw new Error(data.message || 'Failed to fetch logs for export');\n    }\n    return response.json();\n  },\n\n  exportToXlsx(logs, filters) {\n    if (!logs || logs.length === 0) {\n      throw new Error('No logs to export');\n    }\n\n    // Get all unique field names from logs (excluding internal fields starting with _)\n    const allFields = new Set();\n    logs.forEach(log => {\n      Object.keys(log).forEach(key => {\n        if (!key.startsWith('_') || key === '_ip' || key === '_receivedAt') {\n          allFields.add(key);\n        }\n      });\n    });\n\n    // Define column order: timestamp and IP first, then alphabetical\n    const priorityFields = ['_receivedAt', '_ip'];\n    const otherFields = Array.from(allFields)\n      .filter(f => !priorityFields.includes(f))\n      .sort();\n    const orderedFields = [...priorityFields.filter(f => allFields.has(f)), ...otherFields];\n\n    // Create header row with friendly names\n    const headers = orderedFields.map(field => {\n      if (field === '_receivedAt') return 'Timestamp';\n      if (field === '_ip') return 'IP Address';\n      return field.charAt(0).toUpperCase() + field.slice(1);\n    });\n\n    // Create data rows\n    const rows = logs.map(log => {\n      return orderedFields.map(field => {\n        const value = log[field];\n        if (field === '_receivedAt' && value) {\n          return new Date(value).toLocaleString();\n        }\n        if (typeof value === 'object') {\n          return JSON.stringify(value);\n        }\n        return value ?? '';\n      });\n    });\n\n    // Create workbook and worksheet\n    const wb = XLSX.utils.book_new();\n    const wsData = [headers, ...rows];\n    const ws = XLSX.utils.aoa_to_sheet(wsData);\n\n    // Set column widths\n    const colWidths = orderedFields.map((field, idx) => {\n      const headerLen = headers[idx].length;\n      const maxDataLen = Math.max(...rows.map(row => String(row[idx]).length));\n      return { wch: Math.min(Math.max(headerLen, maxDataLen, 10), 50) };\n    });\n    ws['!cols'] = colWidths;\n\n    // Add worksheet to workbook\n    XLSX.utils.book_append_sheet(wb, ws, 'Logs');\n\n    // Create info sheet with export details\n    const exportDate = new Date();\n    const infoData = [\n      ['LogTap Export Report'],\n      [],\n      ['Export Date', exportDate.toLocaleString()],\n      ['Total Records', logs.length.toString()],\n      [],\n      ['Applied Filters'],\n      ['Search', filters.search || '(none)'],\n      ['Field', filters.field === '_all' ? 'All Fields' : filters.field],\n      ['Start Date', filters.startDate ? new Date(filters.startDate).toLocaleString() : '(none)'],\n      ['End Date', filters.endDate ? new Date(filters.endDate).toLocaleString() : '(none)']\n    ];\n    const wsInfo = XLSX.utils.aoa_to_sheet(infoData);\n    wsInfo['!cols'] = [{ wch: 15 }, { wch: 30 }];\n    XLSX.utils.book_append_sheet(wb, wsInfo, 'Export Info');\n\n    // Generate filename with date\n    const dateStr = exportDate.toISOString().slice(0, 10);\n    const timeStr = exportDate.toTimeString().slice(0, 8).replace(/:/g, '-');\n    const filename = `logtap-export-${dateStr}_${timeStr}.xlsx`;\n\n    // Download the file\n    XLSX.writeFile(wb, filename);\n\n    return filename;\n  }\n};\n\nwindow.ExportService = ExportService;\n\n\n// ========== hooks/useTheme.jsx ==========\n/**\n * Theme management hook\n */\nfunction useTheme() {\n  const [theme, setTheme] = React.useState(() =>\n    localStorage.getItem('logtap-theme') || 'dark'\n  );\n\n  React.useEffect(() => {\n    document.documentElement.setAttribute('data-theme', theme);\n    localStorage.setItem('logtap-theme', theme);\n  }, [theme]);\n\n  return [theme, setTheme];\n}\n\nwindow.useTheme = useTheme;\n\n\n// ========== hooks/useDebounce.jsx ==========\n/**\n * Debounce hook for delayed value updates\n */\nfunction useDebounce(value, delay) {\n  const [debouncedValue, setDebouncedValue] = React.useState(value);\n\n  React.useEffect(() => {\n    const timer = setTimeout(() => setDebouncedValue(value), delay);\n    return () => clearTimeout(timer);\n  }, [value, delay]);\n\n  return debouncedValue;\n}\n\nwindow.useDebounce = useDebounce;\n\n\n// ========== hooks/useInfiniteScroll.jsx ==========\n/**\n * Infinite scroll hook using Intersection Observer\n */\nfunction useInfiniteScroll(callback, hasMore) {\n  const observer = React.useRef(null);\n\n  const sentinelRef = React.useCallback(node => {\n    if (observer.current) observer.current.disconnect();\n    if (!hasMore) return;\n\n    observer.current = new IntersectionObserver(entries => {\n      if (entries[0].isIntersecting) callback();\n    }, { threshold: 0.1 });\n\n    if (node) observer.current.observe(node);\n  }, [callback, hasMore]);\n\n  return sentinelRef;\n}\n\nwindow.useInfiniteScroll = useInfiniteScroll;\n\n\n// ========== components/Icons.jsx ==========\n/**\n * SVG Icon Components\n */\n\nfunction ThemeIcon() {\n  return (\n    <svg xmlns=\"http://www.w3.org/2000/svg\" className=\"h-5 w-5\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\">\n      <path strokeLinecap=\"round\" strokeLinejoin=\"round\" strokeWidth={2} d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707\" />\n    </svg>\n  );\n}\n\nfunction RefreshIcon() {\n  return (\n    <svg xmlns=\"http://www.w3.org/2000/svg\" className=\"h-5 w-5\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\">\n      <path strokeLinecap=\"round\" strokeLinejoin=\"round\" strokeWidth={2} d=\"M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15\" />\n    </svg>\n  );\n}\n\nfunction ChevronUpIcon() {\n  return (\n    <svg xmlns=\"http://www.w3.org/2000/svg\" className=\"h-5 w-5\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\">\n      <path strokeLinecap=\"round\" strokeLinejoin=\"round\" strokeWidth={2} d=\"M5 15l7-7 7 7\" />\n    </svg>\n  );\n}\n\nfunction ErrorIcon() {\n  return (\n    <svg xmlns=\"http://www.w3.org/2000/svg\" className=\"stroke-current shrink-0 h-6 w-6\" fill=\"none\" viewBox=\"0 0 24 24\">\n      <path strokeLinecap=\"round\" strokeLinejoin=\"round\" strokeWidth=\"2\" d=\"M10 14l2-2m0 0l2-2m-2 2l-2-2m2 2l2 2m7-2a9 9 0 11-18 0 9 9 0 0118 0z\" />\n    </svg>\n  );\n}\n\nfunction ExportIcon() {\n  return (\n    <svg xmlns=\"http://www.w3.org/2000/svg\" className=\"h-5 w-5\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\">\n      <path strokeLinecap=\"round\" strokeLinejoin=\"round\" strokeWidth={2} d=\"M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z\" />\n    </svg>\n  );\n}\n\nfunction LoadingIcon() {\n  return (\n    <span className=\"loading loading-spinner loading-sm\"></span>\n  );\n}\n\nwindow.ThemeIcon = ThemeIcon;\nwindow.RefreshIcon = RefreshIcon;\nwindow.ChevronUpIcon = ChevronUpIcon;\nwindow.ErrorIcon = ErrorIcon;\nwindow.ExportIcon = ExportIcon;\nwindow.LoadingIcon = LoadingIcon;\n\n\n// ========== components/Header.jsx ==========\n/**\n * Header Component with logo, title, and controls\n */\n\nfunction ThemeSelector({ theme, setTheme }) {\n  return (\n    <div className=\"dropdown dropdown-end\">\n      <div tabIndex={0} role=\"button\" className=\"btn btn-ghost btn-circle\">\n        <ThemeIcon />\n      </div>\n      <ul tabIndex={0} className=\"dropdown-content menu bg-base-100 rounded-box z-10 w-52 p-2 shadow\">\n        <li><button onClick={() => setTheme('light')}>Light</button></li>\n        <li><button onClick={() => setTheme('dark')}>Dark</button></li>\n      </ul>\n    </div>\n  );\n}\n\nfunction Header({ config, theme, setTheme, onRefresh }) {\n  return (\n    <div className=\"navbar bg-base-100 shadow-lg sticky top-0 z-50\">\n      <div className=\"flex-1 gap-3\">\n        {config.LOGO && (\n          <img src={config.LOGO} alt=\"LogTap\" className=\"h-34 w-100 rounded\" />\n        )}        \n      </div>\n      <div className=\"flex-none gap-2\">\n        <span className=\"badge badge-ghost\">v{config.VERSION}</span>\n        <ThemeSelector theme={theme} setTheme={setTheme} />\n        <button className=\"btn btn-ghost btn-circle\" onClick={onRefresh} title=\"Refresh\">\n          <RefreshIcon />\n        </button>\n      </div>\n    </div>\n  );\n}\n\nwindow.ThemeSelector = ThemeSelector;\nwindow.Header = Header;\n\n\n// ========== components/Stats.jsx ==========\n/**\n * Stats Component - displays log statistics\n */\n\nfunction Stats({ total, showing, lastUpdated }) {\n  return (\n    <div className=\"stats shadow w-full mb-6 bg-base-100\">\n      <div className=\"stat\">\n        <div className=\"stat-title\">Total Logs</div>\n        <div className=\"stat-value text-primary\">\n          {total >= 0 ? total.toLocaleString() : '-'}\n        </div>\n      </div>\n      <div className=\"stat\">\n        <div className=\"stat-title\">Loaded</div>\n        <div className=\"stat-value text-secondary\">\n          {showing >= 0 ? showing.toLocaleString() : '-'}\n        </div>\n      </div>\n      <div className=\"stat\">\n        <div className=\"stat-title\">Last Updated</div>\n        <div className=\"stat-value text-sm\">{lastUpdated || '-'}</div>\n      </div>\n    </div>\n  );\n}\n\nwindow.Stats = Stats;\n\n\n// ========== components/Filters.jsx ==========\n/**\n * Filters Component - search and filter controls\n */\n\nfunction Filters({ filters, setFilters, fields, onApply, onClear, onExport, exporting }) {\n  const handleChange = (key, value) => {\n    setFilters(prev => ({ ...prev, [key]: value }));\n  };\n\n  return (\n    <div className=\"card bg-base-100 shadow-xl mb-6\">\n      <div className=\"card-body\">\n        <h2 className=\"card-title mb-4\">Filters</h2>\n        <div className=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4\">\n          <div className=\"form-control\">\n            <label className=\"label\">\n              <span className=\"label-text\">Search</span>\n            </label>\n            <input\n              type=\"text\"\n              placeholder=\"Search logs...\"\n              className=\"input input-bordered\"\n              value={filters.search}\n              onChange={(e) => handleChange('search', e.target.value)}\n            />\n          </div>\n          <div className=\"form-control\">\n            <label className=\"label\">\n              <span className=\"label-text\">Field</span>\n            </label>\n            <select\n              className=\"select select-bordered\"\n              value={filters.field}\n              onChange={(e) => handleChange('field', e.target.value)}\n            >\n              <option value=\"_all\">All Fields</option>\n              <option value=\"_ip\">IP Address</option>\n              {fields.map(f => (\n                <option key={f} value={f}>\n                  {f.charAt(0).toUpperCase() + f.slice(1)}\n                </option>\n              ))}\n            </select>\n          </div>\n          <div className=\"form-control\">\n            <label className=\"label\">\n              <span className=\"label-text\">Start Date</span>\n            </label>\n            <input\n              type=\"datetime-local\"\n              className=\"input input-bordered\"\n              value={filters.startDate}\n              onChange={(e) => handleChange('startDate', e.target.value)}\n            />\n          </div>\n          <div className=\"form-control\">\n            <label className=\"label\">\n              <span className=\"label-text\">End Date</span>\n            </label>\n            <input\n              type=\"datetime-local\"\n              className=\"input input-bordered\"\n              value={filters.endDate}\n              onChange={(e) => handleChange('endDate', e.target.value)}\n            />\n          </div>\n        </div>\n        <div className=\"card-actions justify-between mt-4\">\n          <button\n            className=\"btn btn-success gap-2\"\n            onClick={onExport}\n            disabled={exporting}\n          >\n            {exporting ? <LoadingIcon /> : <ExportIcon />}\n            {exporting ? 'Exporting...' : 'Export to Excel'}\n          </button>\n          <div className=\"flex gap-2\">\n            <button className=\"btn btn-ghost\" onClick={onClear}>\n              Clear Filters\n            </button>\n            <button className=\"btn btn-primary\" onClick={onApply}>\n              Apply\n            </button>\n          </div>\n        </div>\n      </div>\n    </div>\n  );\n}\n\nwindow.Filters = Filters;\n\n\n// ========== components/LogTable.jsx ==========\n/**\n * Log Table Component - displays logs with infinite scroll\n */\n\nfunction truncate(str, len) {\n  return str.length > len ? str.substring(0, len) + '...' : str;\n}\n\nfunction LogRow({ log, index, onClick }) {\n  const timestamp = new Date(log._receivedAt).toLocaleString();\n  const fieldEntries = Object.entries(log).filter(([k]) => !k.startsWith('_'));\n  const displayFields = fieldEntries.slice(0, 3);\n  const hasMore = fieldEntries.length > 3;\n\n  return (\n    <tr className=\"log-row cursor-pointer fade-in hover:bg-base-200\" onClick={onClick}>\n      <td>\n        <span className=\"badge badge-ghost badge-sm\">{index + 1}</span>\n      </td>\n      <td className=\"text-sm\">{timestamp}</td>\n      <td className=\"text-sm font-mono\">{log._ip || '-'}</td>\n      <td>\n        {displayFields.map(([key, value]) => (\n          <span key={key} className=\"badge badge-outline badge-sm mr-1\">\n            {key}: {truncate(String(value), 20)}\n          </span>\n        ))}\n        {hasMore && (\n          <span className=\"badge badge-ghost badge-sm\">\n            +{fieldEntries.length - 3} more\n          </span>\n        )}\n      </td>\n    </tr>\n  );\n}\n\nfunction LogTable({ logs, onSelectLog, loading, loadingMore, sentinelRef, total }) {\n  if (loading && logs.length === 0) {\n    return (\n      <div className=\"card bg-base-100 shadow-xl\">\n        <div className=\"card-body p-0\">\n          <div className=\"flex justify-center py-16\">\n            <span className=\"loading loading-spinner loading-lg\"></span>\n          </div>\n        </div>\n      </div>\n    );\n  }\n\n  return (\n    <div className=\"card bg-base-100 shadow-xl\">\n      <div className=\"card-body p-0\">\n        <div className=\"scroll-container\">\n          <table className=\"table table-zebra\">\n            <thead className=\"sticky top-0 bg-base-200 z-10\">\n              <tr>\n                <th className=\"w-16\">#</th>\n                <th>Timestamp</th>\n                <th>IP</th>\n                <th>Fields</th>\n              </tr>\n            </thead>\n            <tbody>\n              {logs.length === 0 ? (\n                <tr>\n                  <td colSpan=\"4\" className=\"text-center py-8 text-base-content/60\">\n                    No logs found\n                  </td>\n                </tr>\n              ) : (\n                logs.map((log, index) => (\n                  <LogRow\n                    key={log._id || index}\n                    log={log}\n                    index={index}\n                    onClick={() => onSelectLog(log)}\n                  />\n                ))\n              )}\n            </tbody>\n          </table>\n\n          {/* Infinite scroll sentinel */}\n          {logs.length > 0 && logs.length < total && (\n            <div ref={sentinelRef} className=\"loading-sentinel flex justify-center py-4\">\n              {loadingMore && (\n                <span className=\"loading loading-spinner loading-md\"></span>\n              )}\n            </div>\n          )}\n\n          {logs.length > 0 && logs.length >= total && (\n            <div className=\"text-center py-4 text-base-content/50 text-sm\">\n              All {total.toLocaleString()} logs loaded\n            </div>\n          )}\n        </div>\n      </div>\n    </div>\n  );\n}\n\nwindow.truncate = truncate;\nwindow.LogRow = LogRow;\nwindow.LogTable = LogTable;\n\n\n// ========== components/LogDetailModal.jsx ==========\n/**\n * Log Detail Modal Component - shows full log details\n */\n\nfunction LogDetailModal({ log, onClose }) {\n  if (!log) return null;\n\n  const handleCopy = () => {\n    navigator.clipboard.writeText(JSON.stringify(log, null, 2));\n  };\n\n  return (\n    <dialog className=\"modal modal-open\">\n      <div className=\"modal-box max-w-3xl\">\n        <h3 className=\"font-bold text-lg mb-4\">Log Details</h3>\n        <pre className=\"log-details bg-base-200 p-4 rounded-lg overflow-auto max-h-96\">\n          {JSON.stringify(log, null, 2)}\n        </pre>\n        <div className=\"modal-action\">\n          <button className=\"btn btn-ghost\" onClick={handleCopy}>\n            Copy\n          </button>\n          <button className=\"btn\" onClick={onClose}>\n            Close\n          </button>\n        </div>\n      </div>\n      <div className=\"modal-backdrop\" onClick={onClose}></div>\n    </dialog>\n  );\n}\n\nwindow.LogDetailModal = LogDetailModal;\n\n\n// ========== components/ScrollToTop.jsx ==========\n/**\n * Scroll to Top Button Component\n */\n\nfunction ScrollToTop() {\n  const [visible, setVisible] = React.useState(false);\n\n  React.useEffect(() => {\n    const container = document.querySelector('.scroll-container');\n    if (!container) return;\n\n    const handleScroll = () => setVisible(container.scrollTop > 300);\n    container.addEventListener('scroll', handleScroll);\n    return () => container.removeEventListener('scroll', handleScroll);\n  }, []);\n\n  const scrollToTop = () => {\n    document.querySelector('.scroll-container')?.scrollTo({\n      top: 0,\n      behavior: 'smooth'\n    });\n  };\n\n  if (!visible) return null;\n\n  return (\n    <button\n      className=\"btn btn-circle btn-primary fixed bottom-6 right-6 shadow-lg z-50\"\n      onClick={scrollToTop}\n    >\n      <ChevronUpIcon />\n    </button>\n  );\n}\n\nwindow.ScrollToTop = ScrollToTop;\n\n\n// ========== App.jsx ==========\n/**\n * Main App Component\n */\n\nfunction App({ config }) {\n  const [theme, setTheme] = useTheme();\n  const [logs, setLogs] = React.useState([]);\n  const [total, setTotal] = React.useState(-1);\n  const [loading, setLoading] = React.useState(true);\n  const [loadingMore, setLoadingMore] = React.useState(false);\n  const [error, setError] = React.useState(null);\n  const [lastUpdated, setLastUpdated] = React.useState(null);\n  const [fields, setFields] = React.useState([]);\n  const [selectedLog, setSelectedLog] = React.useState(null);\n  const [exporting, setExporting] = React.useState(false);\n  const [filters, setFilters] = React.useState({\n    search: '',\n    field: '_all',\n    startDate: '',\n    endDate: ''\n  });\n\n  const debouncedSearch = useDebounce(filters.search, 300);\n\n  // Fetch available fields from /api/fields\n  const fetchFields = React.useCallback(async () => {\n    try {\n      const data = await LogService.fetchFields(config.TOKEN);\n      if (data.fields?.length > 0) {\n        setFields(data.fields);\n      }\n    } catch (err) {\n      console.error('Failed to fetch fields:', err.message);\n    }\n  }, [config.TOKEN]);\n\n  // Fetch logs from API\n  const fetchLogs = React.useCallback(async (reset = false) => {\n    const skip = reset ? 0 : logs.length;\n\n    if (reset) {\n      setLoading(true);\n      setError(null);\n    } else {\n      setLoadingMore(true);\n    }\n\n    try {\n      const data = await LogService.fetchLogs({\n        token: config.TOKEN,\n        skip,\n        limit: config.PAGE_SIZE,\n        search: debouncedSearch,\n        field: filters.field,\n        startDate: filters.startDate,\n        endDate: filters.endDate\n      });\n\n      if (reset) {\n        setLogs(data.logs);\n      } else {\n        setLogs(prev => [...prev, ...data.logs]);\n      }\n\n      setTotal(data.total);\n      setLastUpdated(new Date().toLocaleTimeString());\n    } catch (err) {\n      setError(err.message);\n    } finally {\n      setLoading(false);\n      setLoadingMore(false);\n    }\n  }, [logs.length, debouncedSearch, filters.field, filters.startDate, filters.endDate, config]);\n\n  // Load more logs for infinite scroll\n  const loadMore = React.useCallback(() => {\n    if (!loadingMore && logs.length < total) {\n      fetchLogs(false);\n    }\n  }, [loadingMore, logs.length, total, fetchLogs]);\n\n  // Infinite scroll sentinel ref\n  const sentinelRef = useInfiniteScroll(loadMore, logs.length < total && !loadingMore);\n\n  // Fetch fields on initial load\n  React.useEffect(() => {\n    fetchFields();\n  }, [fetchFields]);\n\n  // Fetch logs on initial load and auto-refresh\n  React.useEffect(() => {\n    fetchLogs(true);\n    const interval = setInterval(() => {\n      fetchLogs(true);\n      fetchFields(); // Also refresh fields periodically\n    }, config.AUTO_REFRESH_INTERVAL);\n    return () => clearInterval(interval);\n  }, [debouncedSearch, filters.field, filters.startDate, filters.endDate]);\n\n  // Handlers\n  const handleRefresh = () => {\n    fetchLogs(true);\n    fetchFields();\n  };\n\n  const handleClearFilters = () => {\n    setFilters({ search: '', field: '_all', startDate: '', endDate: '' });\n  };\n\n  const handleApplyFilters = () => fetchLogs(true);\n\n  const handleExport = async () => {\n    setExporting(true);\n    try {\n      const data = await ExportService.fetchAllLogs({\n        token: config.TOKEN,\n        search: debouncedSearch,\n        field: filters.field,\n        startDate: filters.startDate,\n        endDate: filters.endDate\n      });\n\n      if (data.logs && data.logs.length > 0) {\n        ExportService.exportToXlsx(data.logs, filters);\n      } else {\n        alert('No logs to export');\n      }\n    } catch (err) {\n      alert('Export failed: ' + err.message);\n    } finally {\n      setExporting(false);\n    }\n  };\n\n  return (\n    <div>\n      <Header\n        config={config}\n        theme={theme}\n        setTheme={setTheme}\n        onRefresh={handleRefresh}\n      />\n\n      <div className=\"container mx-auto p-4 max-w-7xl main-content\">\n        <Stats\n          total={total}\n          showing={logs.length}\n          lastUpdated={lastUpdated}\n        />\n\n        <Filters\n          filters={filters}\n          setFilters={setFilters}\n          fields={fields}\n          onApply={handleApplyFilters}\n          onClear={handleClearFilters}\n          onExport={handleExport}\n          exporting={exporting}\n        />\n\n        {error ? (\n          <div className=\"alert alert-error mb-6\">\n            <ErrorIcon />\n            <span>Error: {error}</span>\n          </div>\n        ) : (\n          <LogTable\n            logs={logs}\n            onSelectLog={setSelectedLog}\n            loading={loading}\n            loadingMore={loadingMore}\n            sentinelRef={sentinelRef}\n            total={total}\n          />\n        )}\n      </div>\n\n      <LogDetailModal\n        log={selectedLog}\n        onClose={() => setSelectedLog(null)}\n      />\n      <ScrollToTop />\n    </div>\n  );\n}\n\nwindow.App = App;\n\n";
